//! 📌️ A child checkpoint borrows the original authored metadata, skips clean history and captures one exact native pin in bounded turns.
use super::*;
use semio_os_kernel::os_store::{ArtifactNativeVcsRequest,ArtifactNativeVcsResult,SpaceMember};
use semio_os_kernel::os_vcs::{Author,CompositionPin,io::binary::checkpoint_identity::original::pending::OriginalPendingEditIds};
use semio_framework_artifact_reference::{ArtifactRef,ArtifactDialect};
use semio_framework_job::{OriginalConstructionAdmission,OriginalSourceBinding,OriginalTurnFailure,StepContext};
use semio_framework_value::{OriginalRetirementFailure,RetirementDemand,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{NativeAllocationIdentity,RetainedCloneClose,RetainedCloneOwner,RetainedCloneSource}};
use semio_plugin_job_receiving::original_steps::{adopted,built,built_with,funded,replied,retired,retired_poll,unbuilt};
use std::mem::{ManuallyDrop,size_of};
/// 🧾️ The parent's original authored metadata remains a unique source throughout its child cascade.
pub type CheckpointMetadata=(Option<String>,Vec<Author>);
/// 🪆️ A single live child owns its probe, copied request and exact VCS continuation until the resulting pin is taken.
pub struct ChildCheckpointUnit{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),body:usize,probe:OriginalPendingEditIds,metadata:ManuallyDrop<Option<RetainedCloneOwner<CheckpointMetadata>>>,request:ManuallyDrop<Option<ArtifactNativeVcsRequest>>,command:ManuallyDrop<Option<Box<ChildVcsCommandUnit>>>,result:Option<ArtifactNativeVcsResult>,fields:ManuallyDrop<Option<[String;5]>>,pin:ManuallyDrop<Option<CompositionPin>>,retirement:RetainedCloneClose,construction:OriginalConstructionAdmission,field:usize,offset:usize,phase:u8,closing:bool}
impl ChildCheckpointUnit{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()}}
 pub fn admit(cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::capture_demands();let settled=built_with(cx,admission,output,original(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,probe:OriginalPendingEditIds::probe(),metadata:ManuallyDrop::new(None),request:ManuallyDrop::new(None),command:ManuallyDrop::new(None),result:None,fields:ManuallyDrop::new(Some(Default::default())),pin:ManuallyDrop::new(None),retirement:Default::default(),construction:Default::default(),field:0,offset:0,phase:0,closing:false}),paid(d))))?;Ok(adopted(settled,admission,output,|owner|&mut owner.construction))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn action(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut Self)->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{let mut done=None;let mut admission=std::mem::take(&mut self.construction);let settled=built(cx,&mut admission,&mut done,original(d),||{run(self)?;Ok(((),paid(d)))});self.construction=admission;settled?;Ok(done.is_some())}
 fn field<'a,M:SpaceMember>(&self,member:&'a M)->Result<&'a str,ValueError>{let identity=member.member_identity().ok_or_else(invalid)?;match self.field{0=>Ok(identity.artifact_id),1=>Ok(&identity.dialect.artifact_kind),2=>Ok(&identity.dialect.standard),3=>Ok(&identity.dialect.subset),4=>member.native_checkpoint_id().ok_or_else(invalid),_=>Err(invalid())}}
 pub fn next_construction_demands<M:SpaceMember>(&self,member:&M)->Option<RetirementDemand>{match self.phase{4=>Some(ChildVcsCommandUnit::capture_demands()),5=>self.command.as_ref().and_then(|c|c.next_construction_demands(member)),_=>None}}
 pub fn progress(&self)->(u8,Option<u8>){(self.phase,self.command.as_ref().map(|c|c.phase()))}
 pub fn ready(&self)->bool{self.phase==11&&!self.closing}
 pub fn advance<M:SpaceMember>(&mut self,member:&mut M,source:&RetainedCloneSource<CheckpointMetadata>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original child checkpoint was cancelled").into())}match self.phase{
 0=>{if let Some(dirty)=self.probe.pending_found(){self.action(cx,header::<u8>(),|s|{s.phase=if dirty{1}else{6};Ok(())})?;}else{let d=member.native_checkpoint_probe_demands(&self.probe)?;let g=cx.retained_grant();let mut done=None;built(cx,&mut self.construction,&mut done,original(d),||Ok(((),member.advance_native_checkpoint_probe(&mut self.probe,g)?)))?;}},
 1=>{let d=header::<RetainedCloneOwner<CheckpointMetadata>>();if built(cx,&mut self.construction,&mut self.metadata,original(d),||Ok((RetainedCloneOwner::default(),paid(d))))?{self.phase=2;}},
 2=>{let owner=self.metadata.as_mut().ok_or_else(invalid)?;let view=source.try_borrow()?;let maximum=cx.fuel_remaining();let d=owner.advance_demands(view,self.body,maximum)?;let body=self.body;funded(cx,d,|effect|replied::<OriginalRetirementFailure>(effect,|effect,reply|owner.advance_into(view,body,maximum,effect,reply).map(drop)))?;if owner.output_ready(){self.phase=3;}},
 3=>{let owner=self.metadata.as_mut().ok_or_else(invalid)?;let d=owner.take_demand()?;let mut taken=None;funded(cx,d,|effect|replied::<ValueError>(effect,|effect,reply|owner.take(&mut taken,effect,reply).map(drop)))?;if let Some((message,authors))=taken{*self.request=Some(ArtifactNativeVcsRequest::CommitCheckpoint{message,authors});self.phase=4;}},
 4=>{if ChildVcsCommandUnit::admit(&mut self.request,cx,&mut self.construction,&mut self.command)?{self.phase=5;}},
 5=>{let owner=self.command.as_mut().ok_or_else(invalid)?;if !owner.ready(){owner.advance(member,cx)?;}else if owner.take_result(cx,&mut self.result)?{self.phase=6;}},
 6=>{if !self.close_children(member,cx)?{return Ok(false)}self.action(cx,header::<u8>(),|s|{s.phase=if member.native_checkpoint_id().is_some(){7}else{11};Ok(())})?;},
 7=>{let text=self.field(member)?;let d=RetirementDemand{capacity_bytes:text.len(),..header::<String>()};self.action(cx,d,|s|{let text=s.field(member)?;s.fields.as_mut().unwrap()[s.field].try_reserve_exact(text.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original child checkpoint pin field reservation failed"))?;s.offset=0;s.phase=8;Ok(())})?;},
 8=>{let text=self.field(member)?;let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1;}let d=RetirementDemand{copy_bytes:end-self.offset+size_of::<(usize,u8)>(),depth:1,..Default::default()};self.action(cx,d,|s|{s.fields.as_mut().unwrap()[s.field].push_str(&text[s.offset..end]);s.offset=end;if end==text.len(){s.field+=1;s.phase=if s.field==5{9}else{7};}Ok(())})?;},
 9=>{self.action(cx,header::<(CompositionPin,Option<[String;5]>,u8)>(),|s|{let[artifact_id,artifact_kind,standard,subset,checkpoint_id]=s.fields.take().ok_or_else(invalid)?;*s.pin=Some(CompositionPin{child_ref:ArtifactRef{artifact_id,dialect:ArtifactDialect{artifact_kind,standard,subset}},checkpoint_id});s.phase=10;Ok(())})?;},
 10=>{self.action(cx,header::<u8>(),|s|{s.phase=11;Ok(())})?;},11=>{},_=>return Err(invalid().into()),}Ok(self.ready())}
 pub fn take_pin(&mut self,cx:&mut StepContext<'_>,output:&mut Option<(bool,Option<CompositionPin>)>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready(){return Err(invalid().into())}let d=header::<(bool,Option<CompositionPin>,u8)>();let mut admission=std::mem::take(&mut self.construction);let settled=built(cx,&mut admission,output,original(d),||{self.phase=12;Ok(((self.result.is_some(),self.pin.take()),paid(d)))});self.construction=admission;settled}
 fn close_children<M:SpaceMember>(&mut self,member:&mut M,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(owner)=self.command.as_mut(){if !owner.terminal_is_empty(){cx.with_original_retirement(|cx|owner.close_step(member,cx))?;return Ok(false)}let mut d=ChildVcsCommandUnit::release_demands();d.copy_bytes=size_of::<Option<Box<ChildVcsCommandUnit>>>();retired(cx,d,|_|{self.command.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}if let Some(owner)=self.metadata.as_mut(){if !owner.terminal_is_empty(){let d=owner.selected_close_demand(self.body)?;let body=self.body;retired_poll(cx,d,|effect|replied(effect,|effect,reply|owner.close_into(body,effect,reply).map(drop)))?;return Ok(false)}let d=header::<Option<RetainedCloneOwner<CheckpointMetadata>>>();retired(cx,d,|_|{self.metadata.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}if !self.probe.terminal_is_empty(){let d=self.probe.close_demands(self.body)?;retired(cx,d,|effect|self.probe.close_step(effect))?;return Ok(false)}Ok(true)}
 pub fn close_demands<M:SpaceMember>(&self,member:&M)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(owner)=self.command.as_ref(){if owner.terminal_is_empty(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildVcsCommandUnit>>>(),..ChildVcsCommandUnit::release_demands()})}return owner.close_demands(member)}if let Some(owner)=self.metadata.as_ref(){return if owner.terminal_is_empty(){Ok(header::<Option<RetainedCloneOwner<CheckpointMetadata>>>())}else{owner.selected_close_demand(self.body)}}if !self.probe.terminal_is_empty(){return self.probe.close_demands(self.body)}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.request.is_some(){return self.retirement.next_owner_demands::<ArtifactNativeVcsRequest>(true,&None,self.body)}if self.fields.is_some(){return self.retirement.next_owner_demands::<[String;5]>(true,&None,self.body)}if self.pin.is_some(){return self.retirement.next_owner_demands::<CompositionPin>(true,&None,self.body)}if self.result.is_some(){return Ok(header::<Option<ArtifactNativeVcsResult>>())}Ok(Default::default())}
 pub fn close_step<M:SpaceMember>(&mut self,member:&mut M,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(member)?;if !self.closing{retired(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}if !self.close_children(member,cx)?{return Ok(false)}if !self.retirement.is_empty(){let body=self.body;retired_poll(cx,d,|effect|self.retirement.step_granted(body,effect))?;return Ok(self.terminal_is_empty())}if self.request.is_none()&&self.fields.is_none()&&self.pin.is_none()&&self.result.is_none(){return unbuilt(cx,&mut self.construction)}retired(cx,d,|effect|{if self.request.is_some(){return Ok(self.retirement.begin_granted(&mut self.request,effect).result?.ok_or_else(invalid)?)}if self.fields.is_some(){return Ok(self.retirement.begin_granted(&mut self.fields,effect).result?.ok_or_else(invalid)?)}if self.pin.is_some(){return Ok(self.retirement.begin_granted(&mut self.pin,effect).result?.ok_or_else(invalid)?)}self.result=None;Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.probe.terminal_is_empty()&&self.metadata.is_none()&&self.request.is_none()&&self.command.is_none()&&self.fields.is_none()&&self.pin.is_none()&&self.result.is_none()&&self.retirement.is_empty()&&self.construction.terminal_is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for ChildCheckpointUnit{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child checkpoint requires funded closure")}}

#[path="🪆️cascade/🦀️.rs"]
pub mod cascade;
